from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Literal
from uuid import uuid4


Role = Literal["system", "user", "assistant", "tool"]


@dataclass
class ToolUse:
    id: str
    name: str
    input: dict[str, Any]


@dataclass
class Message:
    role: Role
    content: str
    id: str = field(default_factory=lambda: str(uuid4()))
    tool_call_id: str | None = None
    tool_name: str | None = None
    tool_uses: list[ToolUse] = field(default_factory=list)
    is_error: bool = False
    reasoning_content: str | None = None


@dataclass
class AssistantTurn:
    text: str
    tool_uses: list[ToolUse] = field(default_factory=list)
    reasoning_content: str | None = None

    def to_message(self) -> Message:
        return Message(
            role="assistant",
            content=self.text,
            tool_uses=list(self.tool_uses),
            reasoning_content=self.reasoning_content,
        )


@dataclass
class AssistantEvent:
    text: str


@dataclass
class ToolUseEvent:
    name: str
    input: dict[str, Any]


@dataclass
class ToolResultEvent:
    name: str
    ok: bool
    preview: str


@dataclass
class ErrorEvent:
    message: str


QueryEvent = AssistantEvent | ToolUseEvent | ToolResultEvent | ErrorEvent

from __future__ import annotations

import json
import os
from typing import Any, Protocol

from dotenv import load_dotenv

from app.messages import AssistantTurn, Message, ToolUse

load_dotenv()


class ModelClient(Protocol):
    def complete(
        self,
        system_prompt: str,
        messages: list[Message],
        tools: list[dict],
    ) -> AssistantTurn:
        ...


DEEPSEEK_BASE_URL = "https://api.deepseek.com"
DEEPSEEK_MODEL = "deepseek-v4-flash"


def messages_to_chat_messages(messages: list[Message]) -> list[dict[str, Any]]:
    converted: list[dict[str, Any]] = []
    for message in messages:
        if message.role in {"user", "assistant"}:
            item: dict[str, Any] = {"role": message.role, "content": message.content}
            if message.role == "assistant" and message.reasoning_content:
                item["reasoning_content"] = message.reasoning_content
            if message.tool_uses:
                item["tool_calls"] = [
                    {
                        "id": tool_use.id,
                        "type": "function",
                        "function": {
                            "name": tool_use.name,
                            "arguments": json.dumps(tool_use.input),
                        },
                    }
                    for tool_use in message.tool_uses
                ]
            converted.append(item)
            continue

        if message.role == "tool":
            converted.append(
                {
                    "role": "tool",
                    "tool_call_id": message.tool_call_id or "",
                    "content": message.content,
                }
            )
            continue

        if message.role == "system":
            converted.append({"role": "system", "content": message.content})

    return converted


def tool_schemas_to_chat_tools(schemas: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "type": "function",
            "function": {
                "name": schema["name"],
                "description": schema.get("description", ""),
                "parameters": schema.get("input_schema", {"type": "object"}),
            },
        }
        for schema in schemas
    ]


def _get_value(obj: Any, name: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(name, default)
    return getattr(obj, name, default)


def chat_message_to_assistant_turn(message: Any) -> AssistantTurn:
    text = _get_value(message, "content") or ""
    reasoning_content = _get_value(message, "reasoning_content", None)
    tool_uses: list[ToolUse] = []

    for call in _get_value(message, "tool_calls", []) or []:
        function = _get_value(call, "function", {})
        raw_arguments = _get_value(function, "arguments", "{}") or "{}"
        try:
            parsed_arguments = json.loads(raw_arguments)
        except json.JSONDecodeError:
            parsed_arguments = {"_raw": raw_arguments}
        tool_uses.append(
            ToolUse(
                id=_get_value(call, "id", ""),
                name=_get_value(function, "name", ""),
                input=parsed_arguments,
            )
        )

    return AssistantTurn(text=text, tool_uses=tool_uses, reasoning_content=reasoning_content)


class FakeModelClient:
    def __init__(self, turns: list[AssistantTurn]) -> None:
        self._turns = list(turns)
        self.call_count = 0

    def complete(
        self,
        system_prompt: str,
        messages: list[Message],
        tools: list[dict],
    ) -> AssistantTurn:
        if self.call_count >= len(self._turns):
            raise RuntimeError("FakeModelClient has no remaining turns")
        turn = self._turns[self.call_count]
        self.call_count += 1
        return turn


class DeepSeekOpenAIClient:
    def __init__(self, client: Any, model: str = DEEPSEEK_MODEL) -> None:
        self._client = client
        self.model = model

    @classmethod
    def from_env(cls, openai_factory: Any | None = None) -> "DeepSeekOpenAIClient":
        from openai import OpenAI

        factory = openai_factory or OpenAI
        api_key = os.environ["DEEPSEEK_API_KEY"]
        base_url = os.environ.get("DEEPSEEK_BASE_URL", DEEPSEEK_BASE_URL)
        model = os.environ.get("DEEPSEEK_MODEL", DEEPSEEK_MODEL)
        return cls(client=factory(api_key=api_key, base_url=base_url), model=model)

    def complete(
        self,
        system_prompt: str,
        messages: list[Message],
        tools: list[dict],
    ) -> AssistantTurn:
        chat_messages = [{"role": "system", "content": system_prompt}]
        chat_messages.extend(messages_to_chat_messages(messages))
        response = self._client.chat.completions.create(
            model=self.model,
            messages=chat_messages,
            tools=tool_schemas_to_chat_tools(tools),
        )
        print(response)
        return chat_message_to_assistant_turn(response.choices[0].message)

from __future__ import annotations

from pathlib import Path

from app.messages import Message, ToolUse
from app.permissions import PermissionMode, PermissionPolicy
from app.tool_registry import ToolContext, ToolRegistry


class ToolRunner:
    def __init__(
        self,
        registry: ToolRegistry,
        workspace: Path,
        permission_policy: PermissionPolicy | None = None,
    ) -> None:
        self._registry = registry
        self._context = ToolContext(workspace=workspace)
        self._permission_policy = permission_policy or PermissionPolicy(PermissionMode.ALLOW_ALL)

    def tool_schemas(self) -> list[dict]:
        return self._registry.schemas()

    def run_all(self, tool_uses: list[ToolUse]) -> list[Message]:
        return [self._run_one(tool_use) for tool_use in tool_uses]

    def _run_one(self, tool_use: ToolUse) -> Message:
        tool = self._registry.get(tool_use.name)
        if tool is None:
            return self._tool_message(tool_use, f"unknown tool: {tool_use.name}", is_error=True)

        if not self._permission_policy.can_use_tool(tool.name, tool.capability):
            return self._tool_message(
                tool_use,
                f"permission denied for {tool.name} in {self._permission_policy.mode.name}",
                is_error=True,
            )

        try:
            result = tool.run(tool_use.input, self._context)
        except Exception as exc:
            return self._tool_message(tool_use, f"tool failed: {exc}", is_error=True)

        return self._tool_message(tool_use, result.content, is_error=not result.ok)

    def _tool_message(self, tool_use: ToolUse, content: str, is_error: bool) -> Message:
        return Message(
            role="tool",
            content=content,
            tool_call_id=tool_use.id,
            tool_name=tool_use.name,
            is_error=is_error,
        )

