        self._tools: dict[str, Tool] = {}

    def register(self, tool: Tool) -> None:
        if tool.name in self._tools:
            raise ValueError(f"tool already registered: {tool.name}")
        self._tools[tool.name] = tool

    def get(self, name: str) -> Tool | None:
        return self._tools.get(name)

    def schemas(self) -> list[dict[str, Any]]:
        return [tool.schema() for tool in self._tools.values()]

from __future__ import annotations

from enum import Enum


class PermissionMode(Enum):
    ALLOW_ALL = "allow_all"
    READ_ONLY = "read_only"
    DENY_ALL = "deny_all"


class ToolCapability(Enum):
    READ = "read"
    WRITE = "write"
    EXECUTE = "execute"


class PermissionPolicy:
    def __init__(self, mode: PermissionMode) -> None:
        self.mode = mode

    def can_use_tool(self, tool_name: str, capability: ToolCapability) -> bool:
        if self.mode == PermissionMode.ALLOW_ALL:
            return True
        if self.mode == PermissionMode.DENY_ALL:
            return False
        if self.mode == PermissionMode.READ_ONLY:
            return capability == ToolCapability.READ
        return False

from __future__ import annotations

from pathlib import Path

from app.engine import SessionEngine
from app.messages import AssistantEvent, ErrorEvent, ToolResultEvent
from app.model_client import DeepSeekOpenAIClient
from app.permissions import PermissionMode, PermissionPolicy
from app.tool_runner import ToolRunner
from app.tools import create_read_only_registry
from app.transcript import TranscriptStore


def render_event(event) -> str:
    if isinstance(event, AssistantEvent):
        return event.text
    if isinstance(event, ToolResultEvent):
        status = "ok" if event.ok else "error"
        # return f"[tool:{event.name}:{status}] {event.preview}"
    if isinstance(event, ErrorEvent):
        return f"[error] {event.message}"
    return str(event)


def build_engine() -> SessionEngine:
    workspace = Path.cwd()
    registry = create_read_only_registry()
    return SessionEngine(
        model_client=DeepSeekOpenAIClient.from_env(),
        tool_runner=ToolRunner(
            registry=registry,
            workspace=workspace,
            permission_policy=PermissionPolicy(PermissionMode.READ_ONLY),
        ),
        transcript=TranscriptStore(workspace / ".mvp-session.jsonl"),
        system_prompt="You are a coding assistant. Use tools when needed.",
    )


def main() -> None:
    engine = build_engine()
    while True:
        try:
            text = input("> ")
        except EOFError:
            break

        if text.strip() in {"/exit", "exit", "quit"}:
            break

        for event in engine.submit(user_input=text):
            rendered = render_event(event)
            if rendered:
                print(rendered)


if __name__ == "__main__":
    main()

