class BashTool:
    name = "bash"
    description = "Execute a shell command inside the workspace. Returns combined stdout and stderr."
    capability = ToolCapability.EXECUTE

    def __init__(self, default_timeout: int = 30, max_output_chars: int = 10_000) -> None:
        self._default_timeout = default_timeout
        self._max_output_chars = max_output_chars

    def schema(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description,
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The shell command to execute.",
                    },
                    "timeout": {
                        "type": "integer",
                        "description": "Timeout in seconds (default 30).",
                    },
                },
                "required": ["command"],
            },
        }

    def run(self, input: dict[str, Any], context: ToolContext) -> ToolResult:
        command = input.get("command")
        if not isinstance(command, str) or not command.strip():
            return ToolResult(ok=False, content="command must be a non-empty string")

        timeout = input.get("timeout", self._default_timeout)
        if not isinstance(timeout, int) or timeout < 1:
            return ToolResult(ok=False, content="timeout must be a positive integer")

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                cwd=str(context.workspace),
                timeout=timeout,
            )
        except subprocess.TimeoutExpired:
            return ToolResult(
                ok=False,
                content=f"command timed out after {timeout}s:\n{command}",
            )
        except OSError as exc:
            return ToolResult(ok=False, content=f"failed to execute command: {exc}")

        combined = result.stdout + result.stderr
        if len(combined) > self._max_output_chars:
            combined = combined[: self._max_output_chars] + "\n... (output truncated)"

        if result.returncode != 0:
            return ToolResult(
                ok=False,
                content=(
                    f"exit code {result.returncode}\n"
                    f"stdout:\n{result.stdout}\n"
                    f"stderr:\n{result.stderr}"
                ),
            )

        return ToolResult(ok=True, content=combined.strip() or "(no output)")

